<script setup lang="ts">import {ref,onMounted,watch,computed} from 'vue';import {useRoute} from 'vue-router';import {useLab} from '../stores/laboratory';import {useAuth} from '../stores/auth';import {createQualification,approveQualification,downloadQualification} from '../api/qualifications';import {useTask} from '../hooks/useTask';import PageTitle from '../components/common/PageTitle.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StatusBadge from '../components/common/StatusBadge.vue';import {modes} from '../constants/enums';import {number} from '../utils/format';const route=useRoute(),lab=useLab(),auth=useAuth(),data=ref({title:'N02 · 限定范围资格复核',run_id:Number(route.query.run)||0,mode:'calibration_only',scope_low:10,scope_high:85,note:'仅用于本次观测范围内的校准关系研究，不视为原值可互换，不保证个体测量精度。'}),{busy,error,perform}=useTask();const run=computed(()=>lab.runs.find(r=>r.id===data.value.run_id));const presets:Record<string,string>={raw:'仅覆盖本次稳定光源与参考反射率观测范围；原值互换仅限本档案注明条件，不得外推。',calibration_only:'仅用于本次观测范围内的校准关系研究，不视为原值可互换，不保证个体测量精度。'};watch(()=>data.value.run_id,()=>{data.value.mode='calibration_only';});watch(()=>data.value.mode,mode=>{if(Object.values(presets).includes(data.value.note))data.value.note=presets[mode];});onMounted(()=>perform(async()=>{await lab.load();if(!data.value.run_id)data.value.run_id=lab.runs.find(r=>r.status==='completed')?.id||0;}));function submit(){perform(async()=>{await createQualification(data.value);await lab.load();data.value.title='';});}function approve(id:number){perform(async()=>{await approveQualification(id);await lab.load();});}</script><template><PageTitle index="05" title="把资格写在明确的范围里" text="工程师记录用途与范围，负责人复核批准；观察员读取获批的配对交付数据。"/><ErrorNotice :message="error" @retry="perform(lab.load)"/><div class="qualification-layout"><form v-if="auth.canEdit" class="research-form" @submit.prevent="submit"><h2>新的资格记录</h2><label>档案标题<input v-model="data.title" required minlength="2"></label><label>依据研究<select v-model="data.run_id"><option v-for="r in lab.runs.filter(x=>x.status==='completed')" :key="r.id" :value="r.id">#{{r.id}} {{r.name}}</option></select></label><label>资格用途<select v-model="data.mode"><option value="raw" :disabled="!run?.result.raw_eligible">原值互换（需满足数值门槛）</option><option value="calibration_only">仅供校准研究（不视为可互换）</option></select></label><p class="input-note">实际观测X范围 {{run?.result.x_range?.map(v=>number(v,3)).join('—')}}%；下方范围必须包含于其中。</p><div class="form-grid two"><label>适用参考下限 %<input type="number" v-model.number="data.scope_low" min="0" max="100" step=".01" required></label><label>适用参考上限 %<input type="number" v-model.number="data.scope_high" min="0" max="100" step=".01" required></label></div><label>条件、限制与复核说明<textarea v-model="data.note" required minlength="10" maxlength="1000" rows="4"></textarea></label><button class="primary" :disabled="busy||data.scope_low>=data.scope_high">存为待复核记录 →</button></form><section class="qualification-files"><article v-for="q in lab.qualifications" :key="q.id"><div class="file-heading"><p class="eyebrow">QUALIFICATION / {{String(q.id).padStart(3,'0')}}</p><StatusBadge :status="q.status"/></div><h2>{{q.title}}</h2><div class="scope-line"><b>{{q.scope_low}}—{{q.scope_high}}<em>%</em></b><span>{{modes[q.mode]}}<small>依据研究 #{{q.run_id}} / 参考X范围</small></span></div><p>{{q.note}}</p><footer><button v-if="q.status==='draft'&&auth.user?.role==='admin'" class="outline" @click="approve(q.id)" :disabled="busy">复核并批准 ✓</button><small v-if="q.status==='draft'">等待负责人复核</small><template v-else><small>批准人 {{q.approved_by}}</small><button class="text-button" :disabled="busy" @click="perform(()=>downloadQualification(q.id))">导出配对与校准CSV ↓</button></template></footer></article><p v-if="!lab.qualifications.length" class="muted">尚无资格记录。完成研究后，先确定用途和适用范围。</p></section></div></template>
